// Archive engine, TODO to DONE: one Notion request per pass through the loop.
// Order per task: read the blocks, look for an existing archive, create and copy, re-read and compare,
// re-check the source, and only then move it to the trash (reversible for 30 days).
// DATABASE ids (classic Notion API, as required by the n8n credential; single-source databases).
const TODO_DB = 'YOUR_TODO_DATABASE_ID';
const DONE_DB = 'YOUR_DONE_DATABASE_ID';
// ---- CONFIG: adapt to your own Notion databases (see README, Setup) ----
const STAGE_DONE = 'Done'; // option of the select property that marks a task as finished
const P = { // Notion property names
  TITLE: 'Task', // title (both databases)
  STAGE: 'Stage', // select, TODO database
  CHECKBOX: 'Is done', // checkbox, TODO database (alternative way to mark a task as finished)
  FINISH: 'Finish date', // date, TODO database
  SOURCE: 'Source task', // url, DONE database (link back to the original task)
  ARCHIVED_ON: 'Archived on', // date, DONE database
  COMPLETED: 'Completed date', // date, DONE database
};
const TIMEZONE = 'UTC';
// Prefix of the link stored in the DONE database (page id appended without dashes). Any URL that opens the page works.
const NOTION_PAGE_BASE_URL = 'https://www.notion.so/';
const FINISH_FALLBACK = 'empty'; // when the finish date is empty: 'empty' (leave Completed date empty) or 'archive' (use the archive date)
const MAX_STEPS = 3000;
const MAX_BLOCKS = 800;
const SELECTS = ['Project', 'Priority', 'Category']; // select properties copied from TODO to DONE (options must exist in DONE)
const MEDIA = ['image', 'video', 'file', 'pdf', 'audio'];
const COPIABLE = ['paragraph', 'heading_1', 'heading_2', 'heading_3', 'bulleted_list_item', 'numbered_list_item',
  'to_do', 'toggle', 'quote', 'callout', 'code', 'divider', 'equation', 'bookmark', 'embed',
  'table_of_contents', 'breadcrumb', 'link_to_page', 'table', 'table_row', ...MEDIA];
// Writable fields per block type (Notion returns fields on read that it refuses on write).
const TXT = ['rich_text', 'color'];
const WRITABLE = {
  paragraph: TXT, bulleted_list_item: TXT, numbered_list_item: TXT, quote: TXT, toggle: TXT,
  to_do: [...TXT, 'checked'], callout: [...TXT, 'icon'],
  heading_1: [...TXT, 'is_toggleable'], heading_2: [...TXT, 'is_toggleable'], heading_3: [...TXT, 'is_toggleable'],
  code: ['rich_text', 'caption', 'language'], bookmark: ['url', 'caption'], embed: ['url', 'caption'],
  equation: ['expression'], divider: [], breadcrumb: [], table_of_contents: ['color'],
  table: ['table_width', 'has_column_header', 'has_row_header'],
};

const input = $input.first().json;
let s, resp = null;
if (input.state) { s = input.state; resp = input.resp; }
else {
  const body = input.body || {};
  s = {
    phase: 'schema', steps: 0, log: [], tasks: [], idx: 0, cursor: null, cur: null, read: null, write: null,
    dryRun: body.dryRun === true, simErr: typeof body.simErr === 'string' ? body.simErr : '', prefix: typeof body.prefix === 'string' ? body.prefix : '',
    archiveDate: $now.setZone(TIMEZONE).toISODate(), startedAt: $now.toISO(), fatal: null,
  };
}

const R = (method, path, body) => ({ method, path, body: body || null });
const hex = id => id.replace(/-/g, '');
const rt = a => (a || []).map(x => x.plain_text).join('');
const sel = p => (p && p.select ? p.select.name : null);
const trashed = r => r.archived === true || r.in_trash === true;
const isErr = r => r && (r.error !== undefined || r.object === 'error');
const normDate = x => (x ? (x.length > 10 ? new Date(x).toISOString() : x) : null);

function go(phase) { s.phase = phase; return H[phase](null); }
function record(status, detail) {
  const c = s.cur;
  s.log.push({ status, detail: detail || '', task: c.title, source: c.id, archive: c.arcId || null });
  s.idx++; s.cur = null; s.read = null; s.write = null;
  return go('nextTask');
}
// Failure after creation: the archive created by THIS pass is removed (never a pre-existing archive).
function fail(status, detail) {
  const c = s.cur;
  if (c.created && c.arcId && !c.rolledBack) {
    c.rolledBack = true; c.rbStatus = status; c.rbDetail = detail;
    return go('rollback');
  }
  return record(status, detail);
}
function readTree(rootId, target, then) {
  s.read = { queue: [rootId], cursor: null, kids: {}, count: 0, root: rootId, target, then };
  return go('read');
}
function build(id) {
  return (s.read.kids[id] || []).map(b => ({ b, kids: b.has_children && s.read.kids[b.id] ? build(b.id) : null }));
}
function walk(tree, fn) { for (const n of tree) { fn(n); if (n.kids) walk(n.kids, fn); } }
function sig(tree, depth = 0, out = []) {
  for (const n of tree) {
    const t = n.b.type, d = n.b[t] || {};
    let txt = rt(d.rich_text);
    if (t === 'to_do') txt += d.checked ? ' [x]' : ' [ ]';
    if (t === 'code') txt += ' |' + d.language;
    if (t === 'bookmark' || t === 'embed') txt += ' |' + d.url;
    if (MEDIA.includes(t)) txt += ' |' + (d.external ? d.external.url : '') + ' |' + rt(d.caption);
    if (t === 'equation') txt = d.expression;
    if (t === 'table_row') txt = d.cells.map(rt).join(' ¦ ');
    out.push(depth + '|' + t + '|' + txt);
    if (n.kids) sig(n.kids, depth + 1, out);
  }
  return out;
}
function cleanRT(arr) {
  return (arr || []).map(x => {
    const a = x.annotations;
    if (x.type === 'text') return { type: 'text', text: { content: x.text.content, link: x.text.link || null }, annotations: a };
    if (x.type === 'equation') return { type: 'equation', equation: { expression: x.equation.expression }, annotations: a };
    if (x.type === 'mention') {
      const m = x.mention, mt = m.type;
      if (mt === 'user' || mt === 'page' || mt === 'database') return { type: 'mention', mention: { type: mt, [mt]: { id: m[mt].id } }, annotations: a };
      if (mt === 'date') return { type: 'mention', mention: { type: 'date', date: m.date }, annotations: a };
    }
    // Mention that cannot be rewritten (link preview, etc.): same text, link kept.
    return { type: 'text', text: { content: x.plain_text, link: x.href ? { url: x.href } : null }, annotations: a };
  });
}
function clean(n) {
  const t = n.b.type, d = JSON.parse(JSON.stringify(n.b[t] || {}));
  delete d.children;
  for (const k of Object.keys(d)) if (d[k] === null || (WRITABLE[t] && !WRITABLE[t].includes(k))) delete d[k];
  if (d.rich_text) d.rich_text = cleanRT(d.rich_text);
  if (d.caption) d.caption = cleanRT(d.caption);
  if (MEDIA.includes(t)) {
    const m = { type: 'external', external: { url: d.external.url }, caption: d.caption || [] };
    if (t === 'file' && d.name) m.name = d.name;
    return { object: 'block', type: t, [t]: m };
  }
  if (t === 'callout' && d.icon && d.icon.type !== 'emoji' && d.icon.type !== 'external') delete d.icon;
  if (t === 'link_to_page') return { object: 'block', type: t, [t]: { type: d.type, [d.type]: d[d.type] } };
  if (t === 'table') {
    d.children = (n.kids || []).map(k => ({ object: 'block', type: 'table_row', table_row: { cells: k.b.table_row.cells.map(cleanRT) } }));
  }
  return { object: 'block', type: t, [t]: d };
}
function finDate(c) {
  if (c.fin && c.fin.start) {
    const d = { start: c.fin.start };
    if (c.fin.end) d.end = c.fin.end;
    if (c.fin.time_zone) d.time_zone = c.fin.time_zone;
    return d;
  }
  return FINISH_FALLBACK === 'archive' ? { start: s.archiveDate } : null;
}
function props(c) {
  const p = {
    [P.TITLE]: { title: cleanRT(c.titleRT) },
    [P.SOURCE]: { url: NOTION_PAGE_BASE_URL + hex(c.id) },
    [P.ARCHIVED_ON]: { date: { start: s.archiveDate } },
  };
  for (const k of SELECTS) if (c[k]) p[k] = { select: { name: c[k] } };
  const d = finDate(c);
  if (d) p[P.COMPLETED] = { date: d };
  return p;
}

const H = {
  schema(r) {
    if (!r) return R('GET', `databases/${DONE_DB}`);
    s.doneOpts = {};
    for (const k of SELECTS) {
      const p = r.properties && r.properties[k];
      s.doneOpts[k] = p && p.select ? p.select.options.map(o => o.name) : [];
    }
    return go('query');
  },
  query(r) {
    if (!r) {
      // Finished = stage set to the done option OR the checkbox ticked (some views have no stage).
      const body = { filter: { or: [{ property: P.STAGE, select: { equals: STAGE_DONE } }, { property: P.CHECKBOX, checkbox: { equals: true } }] }, page_size: 100 };
      if (s.cursor) body.start_cursor = s.cursor;
      return R('POST', `databases/${TODO_DB}/query`, body);
    }
    for (const p of r.results) {
      if (p.object !== 'page' || trashed(p)) continue;
      const pr = p.properties, title = (pr[P.TITLE] && pr[P.TITLE].title) || [];
      const t = { id: p.id, title: rt(title), titleRT: title, edited: p.last_edited_time,
        fin: pr[P.FINISH] && pr[P.FINISH].date ? pr[P.FINISH].date : null };
      for (const k of SELECTS) t[k] = sel(pr[k]);
      if (s.prefix && !t.title.startsWith(s.prefix)) continue;
      s.tasks.push(t);
    }
    if (r.has_more) { s.cursor = r.next_cursor; return H.query(null); }
    s.cursor = null;
    return go('nextTask');
  },
  nextTask() {
    if (s.idx >= s.tasks.length) { s.phase = 'done'; return null; }
    s.cur = JSON.parse(JSON.stringify(s.tasks[s.idx]));
    return readTree(s.cur.id, 'srcTree', 'afterSrc');
  },
  read(r) {
    const rd = s.read;
    if (r) {
      const parent = rd.queue[0];
      rd.kids[parent] = (rd.kids[parent] || []).concat(r.results);
      rd.count += r.results.length;
      if (rd.count > MAX_BLOCKS) return record('kept', `more than ${MAX_BLOCKS} blocks`);
      for (const b of r.results) if (b.has_children && COPIABLE.includes(b.type)) rd.queue.push(b.id);
      if (r.has_more) rd.cursor = r.next_cursor;
      else { rd.cursor = null; rd.queue.shift(); }
    }
    if (rd.queue.length) {
      return R('GET', `blocks/${rd.queue[0]}/children?page_size=100` + (rd.cursor ? `&start_cursor=${encodeURIComponent(rd.cursor)}` : ''));
    }
    s.cur[rd.target] = build(rd.root);
    const then = rd.then;
    s.read = null;
    return go(then);
  },
  afterSrc() {
    const c = s.cur, bad = new Set();
    walk(c.srcTree, n => {
      const t = n.b.type, d = n.b[t] || {};
      if (!COPIABLE.includes(t)) bad.add(t);
      else if (MEDIA.includes(t) && d.type !== 'external') bad.add(`${t} (file hosted by Notion)`);
      else if (t === 'table' && n.kids && n.kids.length > 100) bad.add('table with more than 100 rows');
      else if (t === 'link_to_page' && d.type !== 'page_id' && d.type !== 'database_id') bad.add('link_to_page');
    });
    if (bad.size) return record('kept', 'blocks that cannot be copied: ' + [...bad].join(', '));
    for (const k of SELECTS) {
      if (c[k] && !(s.doneOpts[k] || []).includes(c[k])) return record('kept', `option "${c[k]}" missing from DONE (${k})`);
    }
    return go('search');
  },
  search(r) {
    const c = s.cur;
    if (!r) {
      return R('POST', `databases/${DONE_DB}/query`, { page_size: 10, filter: { or: [
        { property: P.SOURCE, url: { contains: hex(c.id) } },
        { property: P.SOURCE, url: { contains: c.id } },
      ] } });
    }
    const hits = r.results.filter(p => !trashed(p));
    if (hits.length > 1) return record('kept', `${hits.length}${r.has_more ? '+' : ''} archives in DONE for this task: ` + hits.slice(0, 5).map(h => h.id).join(', '));
    if (hits.length === 1) { c.arcId = hits[0].id; c.preexisting = true; return go('verifyProps'); }
    return go('create');
  },
  create(r) {
    const c = s.cur;
    if (!r) {
      // Test only (webhook body): nonexistent target database to provoke a real Notion error.
      const db = s.simErr && c.title.normalize('NFC') === s.simErr.normalize('NFC') ? 'nonexistent-database-id' : DONE_DB;
      return R('POST', 'pages', { parent: { database_id: db }, properties: props(c) });
    }
    c.arcId = r.id; c.created = true;
    s.write = { queue: c.srcTree.length ? [{ target: r.id, kids: c.srcTree }] : [] };
    return go('write');
  },
  write(r) {
    const w = s.write, c = s.cur;
    if (r) {
      const item = w.queue[0], chunk = item.kids.slice(0, 100), res = r.results || [];
      if (res.length !== chunk.length) return fail('error', `partial copy: ${res.length}/${chunk.length} blocks written, archive ${c.arcId} to check`);
      chunk.forEach((n, i) => {
        if (n.kids && n.kids.length && n.b.type !== 'table') w.queue.push({ target: res[i].id, kids: n.kids });
      });
      item.kids = item.kids.slice(100);
      if (!item.kids.length) w.queue.shift();
    }
    if (!w.queue.length) { s.write = null; return go('verifyProps'); }
    const item = w.queue[0];
    return R('PATCH', `blocks/${item.target}/children`, { children: item.kids.slice(0, 100).map(clean) });
  },
  verifyProps(r) {
    const c = s.cur;
    if (!r) return R('GET', `pages/${c.arcId}`);
    const p = r.properties || {}, diffs = [];
    if (trashed(r)) diffs.push('archive in trash');
    if (rt(p[P.TITLE] && p[P.TITLE].title) !== c.title) diffs.push('title');
    for (const k of SELECTS) if (sel(p[k]) !== c[k]) diffs.push(k);
    const src = (p[P.SOURCE] && p[P.SOURCE].url) || '';
    if (!src.replace(/-/g, '').includes(hex(c.id))) diffs.push(P.SOURCE);
    if (c.created) {
      const d = finDate(c), got = p[P.COMPLETED] && p[P.COMPLETED].date;
      if (normDate(d ? d.start : null) !== normDate(got ? got.start : null)) diffs.push(P.COMPLETED);
    }
    if (diffs.length) return fail('kept', (c.preexisting ? 'existing archive' : 'created archive') + ` differs on: ${diffs.join(', ')}`);
    return readTree(c.arcId, 'arcTree', 'compare');
  },
  compare() {
    const c = s.cur, a = sig(c.srcTree), b = sig(c.arcTree);
    const i = a.findIndex((x, j) => x !== b[j]);
    if (a.length !== b.length || i >= 0) {
      return fail('kept', (c.preexisting ? 'existing archive incomplete' : 'incomplete copy')
        + ` (${b.length}/${a.length} blocks, first difference at block ${i >= 0 ? i : Math.min(a.length, b.length)})`);
    }
    c.srcTree = null; c.arcTree = null;
    return go('recheck');
  },
  recheck(r) {
    const c = s.cur;
    if (!r) return R('GET', `pages/${c.id}`);
    if (trashed(r)) return record('already removed', 'source already in trash');
    const pr = r.properties || {};
    if (sel(pr[P.STAGE]) !== STAGE_DONE && !(pr[P.CHECKBOX] && pr[P.CHECKBOX].checkbox === true)) return record('kept', "the task is no longer done (neither the done stage nor the checkbox)");
    if (r.last_edited_time !== c.edited) return record('kept', "task edited during archiving, will be retried on the next run");
    if (s.dryRun) return record(c.preexisting ? 'already present (test, source kept)' : 'archived (test, source kept)');
    return go('trash');
  },
  trash(r) {
    const c = s.cur;
    if (!r) return R('PATCH', `pages/${c.id}`, { archived: true });
    if (!trashed(r)) return record('error', 'trash move not confirmed');
    return record(c.preexisting ? 'already present' : 'archived', c.preexisting ? 'existing archive verified, source removed' : '');
  },
  rollback(r) {
    const c = s.cur;
    if (!r) return R('PATCH', `pages/${c.arcId}`, { archived: true });
    return record(c.rbStatus, c.rbDetail + (trashed(r) ? '; partial archive removed from DONE' : '; partial archive to remove by hand'));
  },
  done() { return null; },
};

let out = null;
try {
  if (resp !== null && isErr(resp)) {
    const e = resp.error || resp;
    const msg = String(e.description || e.message || JSON.stringify(e)).slice(0, 300);
    if (!s.cur) s.fatal = `Notion error at step ${s.phase}: ${msg}`;
    else if (s.phase === 'rollback') out = record(s.cur.rbStatus, `${s.cur.rbDetail}; removing the partial archive failed (${msg}), to be done by hand`);
    else out = fail('error', `step ${s.phase}: ${msg}`);
  } else {
    out = H[s.phase](resp);
  }
} catch (e) {
  s.fatal = `Exception at step ${s.phase}: ${e.message}`;
  out = null;
}
if (out && !s.fatal) {
  s.steps++;
  if (s.steps > MAX_STEPS) { s.fatal = 'Request cap reached'; out = null; }
}
if (out && !s.fatal) return [{ json: { action: 'request', req: out, state: s } }];
return [{ json: { action: 'done', state: s } }];

// Run summary: counters + log (source and archive ids for each task).
const s = $input.first().json.state;
const n = prefix => s.log.filter(l => l.status.startsWith(prefix)).length;
const summary = {
  date: s.archiveDate,
  test: s.dryRun,
  title_filter: s.prefix || null,
  found: s.tasks.length,
  archived: n('archived'),
  already_present: n('already present'),
  already_removed: n('already removed'),
  kept: n('kept'),
  errors: n('error'),
  notion_requests: s.steps,
  fatal: s.fatal,
  current_task_if_fatal: s.fatal && s.cur ? s.cur.title : null,
  log: s.log,
};
const anomalies = summary.kept + summary.errors + (s.fatal ? 1 : 0);
const lines = [
  `🗂️ TODO to DONE archive of ${s.archiveDate}`,
  `Found: ${summary.found} · archived: ${summary.archived} · already present: ${summary.already_present} · kept in TODO: ${summary.kept + summary.errors}`,
];
if (s.fatal) lines.push(`⛔ Stopped: ${s.fatal}` + (summary.current_task_if_fatal ? ` (task "${summary.current_task_if_fatal}")` : ''));
for (const l of s.log.filter(x => x.status.startsWith('kept') || x.status.startsWith('error'))) {
  lines.push(`• "${l.task}": ${l.status}, ${l.detail}`);
}
const html = lines.join('\n').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: { ...summary, anomalies, message: html } }];
